import { useState } from 'react';

const SERVICES = [
  {
    key: 'groww',
    name: 'Groww',
    icon: '📈',
    desc: (info) => info ? `Feeds Wealth · ${info.holdings} holdings · synced ${info.syncedAgo}` : 'Feeds Wealth stock automatically',
    stock: 'WLT',
    status: 'connected',
    color: '#FBBF24',
  },
  {
    key: 'gcal',
    name: 'Google Calendar',
    icon: '📅',
    desc: () => 'Would feed Social stock with events & meetups',
    stock: 'SOC',
    status: 'connect',
    color: '#60A5FA',
  },
  {
    key: 'apple_health',
    name: 'Apple Health',
    icon: '❤️',
    desc: () => 'Would feed Health with steps, sleep & workouts',
    stock: 'HLT',
    status: 'soon',
    label: 'iOS soon',
    color: '#34D399',
  },
  {
    key: 'bank',
    name: 'Bank account',
    icon: '🏦',
    desc: () => 'Would feed Wealth · savings rate tracking',
    stock: 'WLT',
    status: 'soon',
    label: 'Coming soon',
    color: '#FBBF24',
  },
  {
    key: 'strava',
    name: 'Strava',
    icon: '🏃',
    desc: () => 'Would feed Health with workouts & runs',
    stock: 'HLT',
    status: 'soon',
    label: 'Coming soon',
    color: '#34D399',
  },
];

const CURRENCIES = [
  { code: '₹', label: 'INR' },
  { code: '$', label: 'USD' },
  { code: '£', label: 'GBP' },
  { code: '€', label: 'EUR' },
];

export default function SettingsPanel({ onClose, stats = {}, growwInfo = null, currency = '₹', onCurrencyChange }) {
  const [activeCurrency, setActiveCurrency] = useState(currency);

  const handleCurrency = (code) => {
    setActiveCurrency(code);
    onCurrencyChange?.(code);
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 100,
      display: 'flex', justifyContent: 'flex-end',
    }}>
      {/* Backdrop */}
      <div
        style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.6)' }}
        onClick={onClose}
      />

      {/* Panel */}
      <div style={{
        position: 'relative', zIndex: 1,
        width: 380, height: '100%',
        background: 'var(--bg-panel)',
        borderLeft: '1px solid var(--border-warm)',
        overflowY: 'auto',
        animation: 'slideIn 0.25s cubic-bezier(0.4,0,0.2,1)',
        display: 'flex', flexDirection: 'column',
      }}>

        {/* Header */}
        <div style={{ padding: '20px 20px 0', borderBottom: '1px solid var(--border)', paddingBottom: 18 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 46, height: 46, borderRadius: '50%', background: 'rgba(251,191,36,0.12)', border: '2px solid rgba(251,191,36,0.25)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, fontWeight: 700, color: '#FBBF24', fontFamily: 'var(--font-display)' }}>
                SR
              </div>
              <div>
                <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--text-primary)', fontFamily: 'var(--font-display)' }}>Shrithik Raj</div>
                <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2 }}>shrithikraj.com · Vitals (VTL)</div>
              </div>
            </div>
            <button
              onClick={onClose}
              style={{ width: 30, height: 30, borderRadius: 8, background: 'var(--bg-surface)', border: '1px solid rgba(255,255,255,0.08)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, color: 'var(--text-secondary)' }}
            >
              ✕
            </button>
          </div>

          {/* Stats strip */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 8 }}>
            {[
              { val: stats.bestStreak ? `${stats.bestStreak}d` : '—', lbl: 'Best streak' },
              { val: stats.peakVTL ? Math.round(stats.peakVTL).toLocaleString() : '—', lbl: 'Peak VTL' },
              { val: stats.activities || '—', lbl: 'Activities' },
            ].map(s => (
              <div key={s.lbl} style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: 10, padding: '10px 12px', textAlign: 'center' }}>
                <div style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', fontFamily: 'var(--font-mono)' }}>{s.val}</div>
                <div style={{ fontSize: 10, color: 'var(--text-muted)', marginTop: 3, textTransform: 'uppercase', letterSpacing: '0.06em' }}>{s.lbl}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Connected services */}
        <div style={{ padding: '16px 20px', borderBottom: '1px solid var(--border)' }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-muted)', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 12 }}>
            Data sources
          </div>

          {SERVICES.map((svc, i) => (
            <div key={svc.key} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 0', borderBottom: i < SERVICES.length - 1 ? '1px solid rgba(255,255,255,0.04)' : 'none', transition: 'opacity 0.15s' }}>
              <div style={{ width: 38, height: 38, borderRadius: 10, background: svc.status === 'connected' ? `${svc.color}18` : 'rgba(255,255,255,0.04)', border: `1px solid ${svc.status === 'connected' ? svc.color + '30' : 'rgba(255,255,255,0.08)'}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, flexShrink: 0 }}>
                {svc.icon}
              </div>

              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: 600, color: svc.status === 'connected' ? '#EEF0F6' : '#7A8099' }}>
                  {svc.name}
                </div>
                <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2, lineHeight: 1.4 }}>
                  {svc.desc(svc.key === 'groww' ? growwInfo : null)}
                </div>
              </div>

              <div style={{ flexShrink: 0 }}>
                {svc.status === 'connected' && (
                  <span style={{ fontSize: 10, fontWeight: 600, background: 'rgba(52,211,153,0.1)', color: '#34D399', border: '1px solid rgba(52,211,153,0.2)', padding: '3px 9px', borderRadius: 20 }}>
                    Live
                  </span>
                )}
                {svc.status === 'connect' && (
                  <span style={{ fontSize: 10, fontWeight: 600, background: 'var(--bg-surface)', color: 'var(--text-secondary)', border: '1px solid rgba(255,255,255,0.1)', padding: '3px 9px', borderRadius: 20, cursor: 'pointer' }}>
                    Connect
                  </span>
                )}
                {svc.status === 'soon' && (
                  <span style={{ fontSize: 10, fontWeight: 600, background: 'rgba(167,139,250,0.08)', color: '#A78BFA', border: '1px solid rgba(167,139,250,0.15)', padding: '3px 9px', borderRadius: 20 }}>
                    {svc.label}
                  </span>
                )}
              </div>
            </div>
          ))}
        </div>

        {/* Currency preference */}
        <div style={{ padding: '16px 20px', borderBottom: '1px solid var(--border)' }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-muted)', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 12 }}>
            Alert currency
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            {CURRENCIES.map(c => (
              <button key={c.code}
                onClick={() => handleCurrency(c.code)}
                style={{
                  flex: 1, padding: '9px 0', borderRadius: 10, cursor: 'pointer',
                  background: activeCurrency === c.code ? 'rgba(251,191,36,0.12)' : 'rgba(255,255,255,0.04)',
                  border: `1px solid ${activeCurrency === c.code ? 'rgba(251,191,36,0.3)' : 'rgba(255,255,255,0.08)'}`,
                  color: activeCurrency === c.code ? '#FBBF24' : '#4A5168',
                  fontSize: 13, fontWeight: 600, transition: 'all 0.15s',
                  fontFamily: 'var(--font-body)',
                }}
              >
                {c.code} {c.label}
              </button>
            ))}
          </div>
        </div>

        {/* Footer */}
        <div style={{ padding: '14px 20px', marginTop: 'auto' }}>
          <div style={{ fontSize: 11, color: 'var(--text-muted)', textAlign: 'center', lineHeight: 1.6 }}>
            VitalityX v0.1.0 · Currency: Vitals (VTL)<br/>
            <span style={{ color: '#34D399' }}>●</span> All systems operational
          </div>
        </div>

      </div>
    </div>
  );
}
